import unittest

import pipeline


class DedupeHoldoutTests(unittest.TestCase):
    def test_first_record_wins(self):
        records = [
            {"id": 1, "source": "a", "count": 2, "payload": "first"},
            {"id": 1, "source": "b", "count": 9, "payload": "second"},
        ]
        self.assertEqual(pipeline.dedupe(records), [records[0]])

    def test_order_of_first_appearance_is_kept(self):
        records = [
            {"id": 3, "source": "a", "count": 1},
            {"id": 1, "source": "a", "count": 1},
            {"id": 3, "source": "b", "count": 5},
            {"id": 2, "source": "b", "count": 1},
        ]
        self.assertEqual([record["id"] for record in pipeline.dedupe(records)], [3, 1, 2])


class ChunkHoldoutTests(unittest.TestCase):
    def test_partial_chunk_sizes(self):
        self.assertEqual([len(group) for group in pipeline.chunk(list(range(10)), 4)], [4, 4, 2])

    def test_empty_input_yields_no_chunks(self):
        self.assertEqual(pipeline.chunk([], 4), [])


class RunHoldoutTests(unittest.TestCase):
    def test_every_record_reaches_the_summary(self):
        records = [{"id": index, "source": "a", "count": 1} for index in range(5)]
        result = pipeline.run(records, size=2)
        self.assertEqual(result["records"], 5)
        self.assertEqual(result["total_count"], 5)
        self.assertEqual([item["records"] for item in result["chunks"]], [2, 2, 1])

    def test_duplicate_ids_are_dropped_before_counting(self):
        records = [
            {"id": 1, "source": "a", "count": 4},
            {"id": 2, "source": "a", "count": 6},
            {"id": 1, "source": "a", "count": 100},
        ]
        result = pipeline.run(records, size=10)
        self.assertEqual(result["records"], 2)
        self.assertEqual(result["total_count"], 10)


if __name__ == "__main__":
    unittest.main()
